const items = $input.all();
return items.map(item => {
  const data = item.json.body || item.json;
  const errors = [];
  if (!data.request_id) errors.push("Missing required field: request_id");
  if (!data.bidder_name) errors.push("Missing required field: bidder_name");
  if (!data.required_agents) {
    errors.push("Missing required field: required_agents");
  } else if (!Array.isArray(data.required_agents)) {
    errors.push("Field required_agents must be an array");
  }

  return {
    json: {
      ...data,
      valid: errors.length === 0,
      validation_errors: errors
    }
  };
});

const items = $input.all();
return items.map(item => {
  const data = item.json;
  return {
    json: {
      request_id: data.request_id || "UNKNOWN",
      status: "FAILED",
      decision: "MANUAL_REVIEW",
      reason: "Invalid verification request",
      issues: data.validation_errors || ["Request validation failed"],
      timestamp: new Date().toISOString()
    }
  };
});

const items = $input.all();
return items.flatMap(item => {
  const data = item.json;
  const agents = Array.isArray(data.required_agents) ? data.required_agents : [];

  const groups = new Set();
  agents.forEach(agent => {
    const a = agent.toUpperCase();
    if (a.includes("GST") || a.includes("PAN") || a.includes("UDYAM") || a.includes("STATUTORY") || a.includes("MCA") || a.includes("EPFO") || a.includes("ESIC")) {
      groups.add("STATUTORY");
    } else if (a.includes("FINANC") || a.includes("TURNOVER") || a.includes("BALANCE") || a.includes("ITR") || a.includes("CA")) {
      groups.add("FINANCIAL");
    } else if (a.includes("EXPERIENCE") || a.includes("ELIGIBILITY") || a.includes("PAST_PERFORMANCE")) {
      groups.add("EXPERIENCE");
    } else if (a.includes("FORENSIC") || a.includes("DOC") || a.includes("OCR") || a.includes("TAMPER")) {
      groups.add("DOCUMENT_FORENSICS");
    } else if (a.includes("ENTITY") || a.includes("RESOLUT")) {
      groups.add("ENTITY");
    } else if (a.includes("RISK") || a.includes("BLACKLIST") || a.includes("DEBAR")) {
      groups.add("RISK");
    } else if (a.includes("TENDER")) {
      groups.add("TENDER");
    }
  });

  if (groups.size === 0) {
    groups.add("STATUTORY");
  }

  const selectedGroups = Array.from(groups);
  return selectedGroups.map(group => ({
    json: {
      ...data,
      target_group: group,
      selected_groups: selectedGroups,
      required_agents: agents
    }
  }));
});

const items = $input.all();
return items.map(item => {
  const data = item.json;
  return {
    json: {
      ...data,
      statutory_group: "STATUTORY",
      gstin: (data.gstin !== undefined && data.gstin !== null && data.gstin !== "") ? data.gstin : (data.documents && data.documents.gstin ? data.documents.gstin : "27AABCU9603R1ZM"),
      pan: (data.pan !== undefined && data.pan !== null && data.pan !== "") ? data.pan : (data.documents && data.documents.pan ? data.documents.pan : "AABCU9603R"),
      udyam: (data.udyam !== undefined && data.udyam !== null && data.udyam !== "") ? data.udyam : (data.documents && data.documents.udyam ? data.documents.udyam : "UDYAM-TEST-001"),
      note: "Dispatched to specialized statutory child workflows"
    }
  };
});

let initialReq = {};
let selectedGroups = [];
try {
  const selectionData = $('🧠 Agent Selection Engine').first().json;
  selectedGroups = selectionData.selected_groups || [];
  initialReq = selectionData;
} catch (e) {
  try {
    initialReq = $('🔍 Validate Verification Request').first().json || {};
    selectedGroups = initialReq.selected_groups || [];
  } catch (err) {
    initialReq = {};
  }
}

const groupNodeMap = {
  "TENDER": "🧠 Tender Intelligence Agent",
  "STATUTORY": "🔗 Merge Statutory Results",
  "FINANCIAL": "💰 Financial Verification Agent",
  "EXPERIENCE": "🏗 Experience & Eligibility Agent",
  "DOCUMENT_FORENSICS": "🔍 Document Forensics Agent",
  "ENTITY": "🔗 Entity Resolution Agent",
  "RISK": "⚠️ Risk Intelligence Agent"
};

const defaultAgentForNode = {
  "🧠 Tender Intelligence Agent": "TENDER_INTELLIGENCE_AGENT",
  "💰 Financial Verification Agent": "FINANCIAL_AGENT",
  "🏗 Experience & Eligibility Agent": "EXPERIENCE_AGENT",
  "🔍 Document Forensics Agent": "DOCUMENT_FORENSICS_AGENT",
  "🔗 Entity Resolution Agent": "ENTITY_RESOLUTION_AGENT",
  "⚠️ Risk Intelligence Agent": "RISK_INTELLIGENCE_AGENT"
};

function resolveAgent(j, nodeName, group) {
  if (j && j.agent) return j.agent;
  if (nodeName === "🔗 Merge Statutory Results") {
    if (j.gstin || (j.evidence && j.evidence.gstin)) return "GST_AGENT";
    if (j.pan || (j.evidence && j.evidence.pan)) return "PAN_AGENT";
    if (j.udyam || (j.evidence && j.evidence.udyam)) return "UDYAM_AGENT";
    return "STATUTORY_AGENT";
  }
  return defaultAgentForNode[nodeName] || group;
}

let allBranchesDone = true;
const collectedResults = [];

for (const group of selectedGroups) {
  const nodeName = groupNodeMap[group];
  if (!nodeName) continue;

  try {
    const nodeItems = $(nodeName).all();
    if (!nodeItems || nodeItems.length === 0) {
      allBranchesDone = false;
      break;
    }

    for (const item of nodeItems) {
      const j = item.json || {};
      if (j.agent && j.status && j.status !== "ERROR") {
        collectedResults.push(j);
      } else if (j.error || j.status === "ERROR" || j.status === "FAILED") {
        const agentName = resolveAgent(j, nodeName, group);
        collectedResults.push({
          agent: agentName,
          status: j.status || "ERROR",
          confidence: typeof j.confidence === 'number' ? j.confidence : 0.0,
          evidence: j.evidence || (j.error ? { error: j.error } : {}),
          issues: Array.isArray(j.issues) ? j.issues : (j.issues ? [String(j.issues)] : [j.error ? (typeof j.error === 'string' ? j.error : (j.error.message || JSON.stringify(j.error))) : "Child workflow execution failed"]),
          risk_level: "HIGH",
          timestamp: j.timestamp || new Date().toISOString()
        });
      } else if (j.agent) {
        collectedResults.push(j);
      } else if (Array.isArray(j)) {
        collectedResults.push(...j);
      } else {
        const agentName = resolveAgent(j, nodeName, group);
        collectedResults.push({
          agent: agentName,
          status: "ERROR",
          confidence: 0.0,
          evidence: j,
          issues: [j.message || "Child workflow returned unrecognized output format"],
          risk_level: "HIGH",
          timestamp: new Date().toISOString()
        });
      }
    }
  } catch (err) {
    allBranchesDone = false;
    break;
  }
}

if (!allBranchesDone) {
  return [];
}

const reqAgents = initialReq.required_agents || [];

return [{
  json: {
    request_id: initialReq.request_id || "REQ-001",
    tender_id: initialReq.tender_id || "TENDER-001",
    bidder_id: initialReq.bidder_id || "BIDDER-001",
    bidder_name: initialReq.bidder_name || "ABC Technologies Pvt Ltd",
    required_agents: reqAgents,
    agent_results: collectedResults,
    compliance_policy: initialReq.compliance_policy || {},
    raw_input: initialReq
  }
}];

const items = $input.all();
const rawResults = [];

try {
  const collectData = $('📦 Collect Agent Results').first().json;
  if (collectData && Array.isArray(collectData.agent_results)) {
    rawResults.push(...collectData.agent_results);
  }
} catch (e) {
  // fallback if prior node data not directly queried
}

for (const item of items) {
  if (item && item.json) {
    const data = item.json;
    if (Array.isArray(data.agent_results)) {
      rawResults.push(...data.agent_results);
    } else if (Array.isArray(data)) {
      rawResults.push(...data);
    } else {
      rawResults.push(data);
    }
  }
}

let initialReq = {};
try {
  initialReq = $('🔍 Validate Verification Request').first().json || {};
} catch (e) {
  initialReq = rawResults[0] || {};
}

const reqAgents = initialReq.required_agents || [
  "TENDER_INTELLIGENCE_AGENT",
  "GST_AGENT",
  "PAN_AGENT",
  "UDYAM_AGENT",
  "FINANCIAL_AGENT",
  "EXPERIENCE_AGENT",
  "DOCUMENT_FORENSICS_AGENT",
  "ENTITY_RESOLUTION_AGENT",
  "RISK_INTELLIGENCE_AGENT",
  "FINAL_COMPLIANCE_AGENT"
];

const normalized = [];
const seenAgents = new Set();

rawResults.forEach(r => {
  if (r && r.agent && !seenAgents.has(r.agent)) {
    seenAgents.add(r.agent);
    normalized.push({ 
      agent: r.agent,
      status: r.status || "REVIEW",
      confidence: (typeof r.confidence === "number") ? r.confidence : 0.90,
      evidence: r.evidence || {},
      issues: Array.isArray(r.issues) ? r.issues : (r.issues ? [String(r.issues)] : []),
      risk_level: r.risk_level || (r.status === "NOT_VERIFIED" || r.status === "FAILED" ? "HIGH" : (r.status === "REVIEW" ? "MEDIUM" : "LOW")),
      timestamp: r.timestamp || new Date().toISOString()
    });
  } else if (r && r.error) {
    const errAgent = r.agent || "EXECUTION_ERROR";
    if (!seenAgents.has(errAgent)) {
      seenAgents.add(errAgent);
      normalized.push({
        agent: errAgent,
        status: "ERROR",
        confidence: 0.0,
        evidence: { error: r.error },
        issues: [typeof r.error === "string" ? r.error : JSON.stringify(r.error)],
        risk_level: "HIGH",
        timestamp: new Date().toISOString()
      });
    }
  }
});

// For any required agents not returned by child workflows, flag them explicitly
reqAgents.forEach(agentName => {
  if (!seenAgents.has(agentName)) {
    normalized.push({
      agent: agentName,
      status: "NOT_EXECUTED",
      confidence: 0.0,
      evidence: {},
      issues: [`Required agent ${agentName} was not executed or returned no result`],
      risk_level: "HIGH",
      timestamp: new Date().toISOString()
    });
  }
});

return [{
  json: {
    request_id: initialReq.request_id || "REQ-001",
    tender_id: initialReq.tender_id || "TENDER-001",
    bidder_id: initialReq.bidder_id || "BIDDER-001",
    bidder_name: initialReq.bidder_name || "ABC Technologies Pvt Ltd",
    normalized_results: normalized
  }
}];

const items = $input.all();
return items.map(item => {
  const data = item.json;
  const results = data.normalized_results || [];

  let riskScore = 0;
  const warnings = [];
  const failures = [];

  results.forEach(agent => {
    if (agent.status === "FAILED" || agent.status === "NOT_VERIFIED" || agent.status === "ERROR" || agent.status === "NOT_EXECUTED") {
      riskScore += 40;
      failures.push(`${agent.agent} failed verification (${agent.status}): ${(agent.issues || []).join(", ") || "Unresolved discrepancies"}`);
    } else if (agent.status === "WARNING" || agent.status === "REVIEW" || agent.risk_level === "MEDIUM") {
      riskScore += 15;
      warnings.push(`${agent.agent} reported review/warning condition: ${(agent.issues || []).join(", ") || "Discrepancy detected"}`);
    } else if (agent.risk_level === "HIGH") {
      riskScore += 50;
      failures.push(`${agent.agent} flagged high-risk anomalies`);
    }
  });

  riskScore = Math.min(100, Math.max(0, riskScore));

  let riskLevel = "LOW";
  if (riskScore >= 60) {
    riskLevel = "HIGH";
  } else if (riskScore >= 30) {
    riskLevel = "MEDIUM";
  }

  return {
    json: {
      ...data,
      risk_score: riskScore,
      risk_level: riskLevel,
      risk_warnings: warnings,
      risk_failures: failures
    }
  };
});

const items = $input.all();
return items.map(item => {
  const data = item.json;
  const failures = data.risk_failures || [];
  const warnings = data.risk_warnings || [];
  const results = data.normalized_results || [];

  let decision = "QUALIFIED";
  const reasons = [];

  if (results.length === 0) {
    decision = "MANUAL_REVIEW";
    reasons.push("Insufficient verification evidence received from child workflows");
  } else if (failures.length > 0) {
    decision = "NOT_QUALIFIED";
    reasons.push(...failures);
  } else if (warnings.length > 0 || data.risk_level === "MEDIUM") {
    decision = "CONDITIONALLY_QUALIFIED";
    reasons.push(...warnings);
  } else {
    decision = "QUALIFIED";
    reasons.push("All mandatory statutory and eligibility criteria successfully verified");
  }

  return {
    json: {
      ...data,
      decision,
      reasons
    }
  };
});

const items = $input.all();
return items.map(item => {
  const data = item.json;
  return {
    json: {
      verification_id: `VER-${Date.now().toString(36).toUpperCase()}-${Math.floor(Math.random()*1000)}`,
      request_id: data.request_id,
      tender_id: data.tender_id,
      bidder_id: data.bidder_id,
      bidder_name: data.bidder_name,
      status: "COMPLETED",
      decision: data.decision,
      risk_score: data.risk_score,
      risk_level: data.risk_level,
      agent_results: data.normalized_results || [],
      failed_requirements: data.risk_failures || [],
      missing_documents: [],
      warnings: data.risk_warnings || [],
      reasons: data.reasons || [],
      timestamp: new Date().toISOString()
    }
  };
});

const items = $input.all();
return [{
  json: {
    status: "ERROR",
    decision: "MANUAL_REVIEW",
    error: true,
    message: "Verification workflow encountered an error",
    timestamp: new Date().toISOString()
  }
}];
